import React, { useState, useEffect } from "react";
import { Outlet, Link, useNavigate, useLocation } from "react-router-dom";
import {
  FaBookOpen,
  FaChalkboardTeacher,
  FaUserGraduate,
  FaCalendarAlt,
  FaSignOutAlt,
  FaGraduationCap,
  FaTasks,
  FaClipboardList
} from "react-icons/fa";

function MainLayout() {
  const navigate = useNavigate();
  const location = useLocation();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  // 🌙 Dark Mode State
  const [darkMode, setDarkMode] = useState(false);

  // Load saved mode
  useEffect(() => {
    const saved = localStorage.getItem("darkMode");
    if (saved) setDarkMode(JSON.parse(saved));
  }, []);

  // Save mode
  useEffect(() => {
    localStorage.setItem("darkMode", JSON.stringify(darkMode));
    document.body.style.backgroundColor = darkMode ? "#121212" : "#f5f7fb";
  }, [darkMode]);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  // Active link style
  const linkStyle = (path) => ({
    display: "flex",
    alignItems: "center",
    gap: "10px",
    padding: "12px 14px",
    borderRadius: "12px",
    textDecoration: "none",
    color:
      location.pathname === path
        ? "#fff"
        : darkMode
        ? "#ddd"
        : "#333",
    background:
      location.pathname === path
        ? "#7b1fa2"
        : "transparent",
    fontWeight: "600",
    marginBottom: "10px",
    transition: "0.3s"
  });

  return (
    <div
      style={{
        display: "flex",
        minHeight: "100vh",
        background: darkMode ? "#121212" : "#f5f7fb",
        color: darkMode ? "#fff" : "#000"
      }}
    >
      {/* SIDEBAR */}
      <aside
        style={{
          width: "260px",
          background: darkMode ? "#1e1e1e" : "#fff",
          padding: "20px",
          boxShadow: "2px 0 12px rgba(0,0,0,0.06)"
        }}
      >
        {/* LOGO */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "22px",
            fontWeight: "bold",
            color: "#7b1fa2",
            marginBottom: "30px"
          }}
        >
          <FaGraduationCap />
          LMS
        </div>

        {/* DASHBOARD */}
        {role === "teacher" && (
          <Link to="/teacher-dashboard" style={linkStyle("/teacher-dashboard")}>
            <FaChalkboardTeacher />
            Teacher Dashboard
          </Link>
        )}

        {role === "student" && (
          <Link to="/student-dashboard" style={linkStyle("/student-dashboard")}>
            <FaUserGraduate />
            Student Dashboard
          </Link>
        )}

        {/* COURSES */}
        <Link to="/courses" style={linkStyle("/courses")}>
          <FaBookOpen />
          Courses
        </Link>

        {/* ASSIGNMENTS */}
        {role === "teacher" && (
          <Link
            to="/teacher-assignments"
            style={linkStyle("/teacher-assignments")}
          >
            <FaClipboardList />
            Assignments
          </Link>
        )}

        {role === "student" && (
          <Link
            to="/student-assignments"
            style={linkStyle("/student-assignments")}
          >
            <FaClipboardList />
            Assignments
          </Link>
        )}

        {/* QUIZ */}
        {role === "teacher" && (
          <Link to="/teacher-quiz" style={linkStyle("/teacher-quiz")}>
            <FaTasks />
            Quiz
          </Link>
        )}

        {role === "student" && (
          <Link to="/student-quiz" style={linkStyle("/student-quiz")}>
            <FaTasks />
            Quiz
          </Link>
        )}

        {/* MATERIALS */}
        {role === "teacher" && (
          <Link to="/upload-material" style={linkStyle("/upload-material")}>
            📂 Upload Notes
          </Link>
        )}

        {role === "student" && (
          <Link to="/materials" style={linkStyle("/materials")}>
            📚 Materials
          </Link>
        )}

        {/* PLANNER */}
        {role === "student" && (
          <Link to="/planner" style={linkStyle("/planner")}>
            <FaCalendarAlt />
            Planner
          </Link>
        )}
        {role === "student" && (
          <Link to="/smart-planner" style={linkStyle("/smart-planner")}>
            Smart Planner
          </Link>
        )}
        {/* DARK MODE BUTTON */}
        <button
          onClick={() => setDarkMode(!darkMode)}
          style={{
            marginTop: "15px",
            width: "100%",
            padding: "10px",
            borderRadius: "10px",
            border: "none",
            background: darkMode ? "#444" : "#ddd",
            color: darkMode ? "#fff" : "#000",
            cursor: "pointer"
          }}
        >
          {darkMode ? "☀️ Light Mode" : "🌙 Dark Mode"}
        </button>

        {/* LOGOUT */}
        <button
          onClick={handleLogout}
          style={{
            marginTop: "20px",
            width: "100%",
            border: "none",
            background: "#e53935",
            color: "#fff",
            padding: "12px",
            borderRadius: "12px",
            fontWeight: "bold",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: "10px"
          }}
        >
          <FaSignOutAlt />
          Logout
        </button>
      </aside>

      {/* MAIN CONTENT */}
      <main style={{ flex: 1, padding: "25px" }}>
        {/* TOP BAR */}
        <div
          style={{
            background: "linear-gradient(135deg, #7b1fa2, #512da8)",
            color: "#fff",
            borderRadius: "18px",
            padding: "22px",
            marginBottom: "25px",
            boxShadow: "0 8px 24px rgba(123,31,162,0.25)"
          }}
        >
          <h2 style={{ margin: 0 }}>
            Welcome, {userName || "User"} 👋
          </h2>

          <p style={{ marginTop: "8px", opacity: 0.9 }}>
            {role === "teacher"
              ? "Manage your courses, assignments, and quizzes."
              : "Track your learning, planner, assignments, and progress."}
          </p>
        </div>

        {/* PAGE CONTENT */}
        <Outlet />
      </main>
    </div>
  );
}

export default MainLayout;
